import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 권한을 확인하는 메뉴 이름
const MENU_NAME = '예산장부 조회';
// 가정: 한 쪽 기본 크기와 최대 크기
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const LEDGER_TYPES = ['예산일계표', '월계표', '수입·지출부', '자금출납장', '은행이체명세서', '지출원인행위부', '수입징수부', '세출·세입총괄표'];
const CASH_SCOPES = ['전체', '금융기관별', '프로젝트별', '결의 담당자별'];
const FORM_LEDGERS = ['은행이체명세서', '지출원인행위부', '수입징수부'];

const SCOPE_SQL = `
  SELECT mp.view_scope AS "viewScope", e.department_id AS "departmentId"
  FROM menu_permission mp
  JOIN menu m ON m.menu_id = mp.menu_id
  JOIN employee e ON e.employee_id = mp.employee_id
  WHERE mp.employee_id = CAST(:userId AS bigint)
    AND m.name = :menuName
    AND m.use_status = '사용'
  LIMIT 1`;

// 조회 권한 범위(전체/부서/개인)로 결과를 한정한다
const SCOPE_TEXT = ` (CAST(:scope AS text) = '전체'
  OR (CAST(:scope AS text) = '부서' AND er.department_id = CAST(:departmentId AS bigint))
  OR (CAST(:scope AS text) = '개인' AND ad.drafter_id = CAST(:userId AS bigint)))`;

const J_FILTER = ` AND (CAST(:cashBookScope AS text) <> '금융기관별' OR jel.partner_id = CAST(:partnerId AS bigint))
  AND (CAST(:cashBookScope AS text) <> '프로젝트별' OR jel.project_id = CAST(:projectId AS bigint))
  AND (CAST(:cashBookScope AS text) <> '결의 담당자별' OR ad.drafter_id = CAST(:resolverId AS bigint))`;

const R_FILTER = ` AND (CAST(:cashBookScope AS text) <> '금융기관별' OR er.partner_id = CAST(:partnerId AS bigint))
  AND (CAST(:cashBookScope AS text) <> '프로젝트별' OR er.project_id = CAST(:projectId AS bigint))
  AND (CAST(:cashBookScope AS text) <> '결의 담당자별' OR ad.drafter_id = CAST(:resolverId AS bigint))`;

const JOURNAL_JOIN = ` FROM journal_entry je
  JOIN journal_entry_line jel ON jel.journal_entry_id = je.journal_entry_id
  JOIN expense_resolution er ON er.expense_resolution_id = je.expense_resolution_id
  LEFT JOIN approval_document ad ON ad.approval_document_id = er.approval_document_id
  LEFT JOIN budget_account ba ON ba.budget_account_id = jel.budget_account_id`;

const JOURNAL_FROM = JOURNAL_JOIN
  + ` WHERE je.entry_date BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date) AND`
  + SCOPE_TEXT
  + J_FILTER;

const RESOLUTION_JOIN = ` FROM expense_resolution er
  LEFT JOIN approval_document ad ON ad.approval_document_id = er.approval_document_id
  LEFT JOIN partner p ON p.partner_id = er.partner_id`;

const RESOLUTION_FROM = RESOLUTION_JOIN
  + ` WHERE CAST(er.created_at AS date) BETWEEN CAST(:fromDate AS date) AND CAST(:toDate AS date) AND`
  + SCOPE_TEXT
  + R_FILTER;

const INCOME_ONLY = ` AND ba.income_expense_type = '수입'`;
const BANK_ONLY = ` AND EXISTS (SELECT 1 FROM partner_account pa WHERE pa.partner_id = er.partner_id AND pa.use_status = '사용')`;
const PAGING = ` LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`;

const TOTALS_J = `SUM(SUM(jel.debit_amount + jel.credit_amount)) OVER () AS "totalAmount", COUNT(*) OVER () AS "total"`;

const DAILY_SQL = `SELECT je.entry_date AS "entryDate", CAST(NULL AS text) AS summary,
  SUM(jel.debit_amount) AS "debitAmount", SUM(jel.credit_amount) AS "creditAmount",
  CAST(0 AS numeric) AS "resolutionAmount", ${'$'}{TOTALS_J}`;

const DETAIL_SELECT = `SELECT je.entry_date AS "entryDate", COALESCE(jel.summary, je.summary) AS summary,
  jel.debit_amount AS "debitAmount", jel.credit_amount AS "creditAmount",
  er.resolution_amount AS "resolutionAmount",
  SUM(jel.debit_amount + jel.credit_amount) OVER () AS "totalAmount", COUNT(*) OVER () AS "total"`;

const MONTHLY_SELECT = `SELECT CAST(date_trunc('month', je.entry_date) AS date) AS "entryDate", CAST(NULL AS text) AS summary,
  SUM(jel.debit_amount) AS "debitAmount", SUM(jel.credit_amount) AS "creditAmount",
  CAST(0 AS numeric) AS "resolutionAmount",
  SUM(SUM(jel.debit_amount + jel.credit_amount)) OVER () AS "totalAmount", COUNT(*) OVER () AS "total"`;

const DAILY_SELECT = `SELECT je.entry_date AS "entryDate", CAST(NULL AS text) AS summary,
  SUM(jel.debit_amount) AS "debitAmount", SUM(jel.credit_amount) AS "creditAmount",
  CAST(0 AS numeric) AS "resolutionAmount",
  SUM(SUM(jel.debit_amount + jel.credit_amount)) OVER () AS "totalAmount", COUNT(*) OVER () AS "total"`;

const BUDGET_GROUP_SELECT = `SELECT MIN(je.entry_date) AS "entryDate", ba.name AS summary,
  SUM(jel.debit_amount) AS "debitAmount", SUM(jel.credit_amount) AS "creditAmount",
  CAST(0 AS numeric) AS "resolutionAmount",
  SUM(SUM(jel.debit_amount + jel.credit_amount)) OVER () AS "totalAmount", COUNT(*) OVER () AS "total"`;

const RES_DETAIL_SELECT = `SELECT CAST(er.created_at AS date) AS "entryDate", COALESCE(p.name, '') AS summary,
  CAST(0 AS numeric) AS "debitAmount", CAST(0 AS numeric) AS "creditAmount",
  er.resolution_amount AS "resolutionAmount",
  SUM(er.resolution_amount) OVER () AS "totalAmount", COUNT(*) OVER () AS "total"`;

const RES_SUM_SELECT = `SELECT CAST(er.created_at AS date) AS "entryDate", CAST(NULL AS text) AS summary,
  CAST(0 AS numeric) AS "debitAmount", CAST(0 AS numeric) AS "creditAmount",
  SUM(er.resolution_amount) AS "resolutionAmount",
  SUM(SUM(er.resolution_amount)) OVER () AS "totalAmount", COUNT(*) OVER () AS "total"`;

const DETAIL_ORDER = ` ORDER BY je.entry_date, je.journal_entry_id, jel.line_no`;
const RES_DETAIL_ORDER = ` ORDER BY er.created_at, er.expense_resolution_id`;
const RES_SUM_GROUP = ` GROUP BY CAST(er.created_at AS date) ORDER BY CAST(er.created_at AS date)`;

function bad(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function text(v: unknown): string {
  if (typeof v === 'string') return v.trim();
  if (typeof v === 'number') return String(v);
  return '';
}

function idOf(v: unknown, label: string): string | null {
  const s = text(v);
  if (s === '') return null;
  if (!/^\d+$/.test(s)) throw bad(label + ' 형식이 올바르지 않습니다.');
  return s;
}

function dateOf(v: unknown, label: string): string {
  const s = text(v);
  if (s === '') throw bad(label + '을(를) 입력해 주세요.');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) throw bad(label + ' 형식이 올바르지 않습니다.');
  return s;
}

function sqlFor(ledgerType: string, viewForm: string): string {
  const summed = viewForm === '총괄';
  switch (ledgerType) {
    case '예산일계표':
      return DAILY_SELECT + JOURNAL_FROM + ` GROUP BY je.entry_date ORDER BY je.entry_date` + PAGING;
    case '월계표':
      return MONTHLY_SELECT + JOURNAL_FROM
        + ` GROUP BY CAST(date_trunc('month', je.entry_date) AS date) ORDER BY CAST(date_trunc('month', je.entry_date) AS date)` + PAGING;
    case '수입·지출부':
    case '자금출납장':
      return DETAIL_SELECT + JOURNAL_FROM + DETAIL_ORDER + PAGING;
    case '수입징수부':
      if (summed) return BUDGET_GROUP_SELECT + JOURNAL_FROM + INCOME_ONLY + ` GROUP BY ba.name ORDER BY ba.name` + PAGING;
      return DETAIL_SELECT + JOURNAL_FROM + INCOME_ONLY + DETAIL_ORDER + PAGING;
    case '세출·세입총괄표':
      return BUDGET_GROUP_SELECT + JOURNAL_FROM + ` GROUP BY ba.name ORDER BY ba.name` + PAGING;
    case '은행이체명세서':
      if (summed) return RES_SUM_SELECT + RESOLUTION_FROM + BANK_ONLY + RES_SUM_GROUP + PAGING;
      return RES_DETAIL_SELECT + RESOLUTION_FROM + BANK_ONLY + RES_DETAIL_ORDER + PAGING;
    default:
      if (summed) return RES_SUM_SELECT + RESOLUTION_FROM + RES_SUM_GROUP + PAGING;
      return RES_DETAIL_SELECT + RESOLUTION_FROM + RES_DETAIL_ORDER + PAGING;
  }
}

@Controller('api/v1')
export class FnSfr00501Controller {
  @Get('/budget-ledgers')
  async listBudgetLedgers(@Req() req: Request) {
    const user = currentUser(req);
    user.require('예산·회계 담당자');
    const q = checks.queryOf(req.query);

    const ledgerType = text(q['ledgerType']);
    if (ledgerType === '') throw bad('장부 종류를 선택해 주세요.');
    if (!LEDGER_TYPES.includes(ledgerType)) throw bad('장부 종류가 올바르지 않습니다.');
    const fromDate = dateOf(q['fromDate'], '조회 시작일');
    const toDate = dateOf(q['toDate'], '조회 종료일');
    if (fromDate > toDate) throw bad('조회 시작일은 종료일보다 늦을 수 없습니다.');

    let cashBookScope = '전체';
    let partnerId: string | null = null;
    let projectId: string | null = null;
    let resolverId: string | null = null;
    if (ledgerType === '자금출납장') {
      const given = text(q['cashBookScope']);
      if (given !== '') cashBookScope = given;
      if (!CASH_SCOPES.includes(cashBookScope)) throw bad('조회 구분이 올바르지 않습니다.');
      if (cashBookScope === '금융기관별') {
        partnerId = idOf(q['partnerId'], '금융거래처');
        if (partnerId === null) throw bad('금융거래처를 선택해 주세요.');
      }
      if (cashBookScope === '프로젝트별') {
        projectId = idOf(q['projectId'], '프로젝트');
        if (projectId === null) throw bad('프로젝트를 선택해 주세요.');
      }
      if (cashBookScope === '결의 담당자별') {
        resolverId = idOf(q['resolverId'], '결의 담당자');
        if (resolverId === null) throw bad('결의 담당자를 선택해 주세요.');
      }
    }

    let viewForm = '상세';
    if (FORM_LEDGERS.includes(ledgerType)) {
      const given = text(q['viewForm']);
      if (given !== '') viewForm = given;
      if (viewForm !== '상세' && viewForm !== '총괄') throw bad('조회 형태가 올바르지 않습니다.');
    }

    const pageText = text(q['page']);
    const sizeText = text(q['size']);
    const page = pageText === '' ? 0 : Number(pageText);
    let size = sizeText === '' ? DEFAULT_SIZE : Number(sizeText);
    if (!Number.isInteger(page) || page < 0) throw bad('쪽 번호가 올바르지 않습니다.');
    if (!Number.isInteger(size) || size < 1) throw bad('쪽 크기가 올바르지 않습니다.');
    if (size > MAX_SIZE) size = MAX_SIZE;

    const sql = sqlFor(ledgerType, viewForm);

    return transaction(async (db) => {
      const grants = await db.query(SCOPE_SQL, { userId: user.id, menuName: MENU_NAME });
      if (grants.length === 0) {
        throw new ApiError(403, 'FORBIDDEN', '예산장부 조회 권한이 없습니다.');
      }
      const grant = grants[0] as { viewScope: string; departmentId: number };
      const rows = await db.query(sql, {
        fromDate,
        toDate,
        scope: grant.viewScope,
        userId: user.id,
        departmentId: String(grant.departmentId),
        cashBookScope,
        partnerId,
        projectId,
        resolverId,
        size,
        offset: page * size,
      });
      const total = rows.length > 0 ? Number((rows[0] as { total: number }).total) : 0;
      const items = rows.map((r) => {
        const row = r as {
          entryDate: string;
          summary: string | null;
          debitAmount: number;
          creditAmount: number;
          resolutionAmount: number;
          totalAmount: number;
        };
        return {
          entryDate: row.entryDate,
          summary: row.summary,
          debitAmount: Number(row.debitAmount),
          creditAmount: Number(row.creditAmount),
          resolutionAmount: Number(row.resolutionAmount),
          totalAmount: Number(row.totalAmount),
        };
      });
      return { items, page, size, total };
    });
  }
}

