import { useState } from 'react';
import { Band, DataTable, DateInput, DateText, ErrorText, Field, Filters, LookupSelect, Num, Pager, Select, Tiles, call, useData } from '../kit';
import type { Page, PageProps, Row } from '../kit';

const SIZE = 20;
const LEDGER_TYPES = ['예산일계표', '월계표', '수입·지출부', '자금출납장', '은행이체명세서', '지출원인행위부', '수입징수부', '세출·세입총괄표'];
const CASH_SCOPES = ['전체', '금융기관별', '프로젝트별', '결의 담당자별'];
const FORM_LEDGERS = ['은행이체명세서', '지출원인행위부', '수입징수부'];

export default function FnSfr00501Page({ role, notify }: PageProps) {
  const [ledgerType, setLedgerType] = useState('');
  const [fromDate, setFromDate] = useState('');
  const [toDate, setToDate] = useState('');
  const [cashBookScope, setCashBookScope] = useState('전체');
  const [partnerId, setPartnerId] = useState<number | string>('');
  const [projectId, setProjectId] = useState<number | string>('');
  const [resolverId, setResolverId] = useState<number | string>('');
  const [viewForm, setViewForm] = useState('상세');
  const [formError, setFormError] = useState('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [pageNo, setPageNo] = useState(0);

  const { data, error, loading } = useData<Page | undefined>(async () => {
    if (applied === null) return undefined;
    return call<Page>('GET', '/budget-ledgers', role, undefined, { ...applied, page: pageNo, size: SIZE });
  }, [applied, pageNo]);

  const isCash = ledgerType === '자금출납장';
  const hasForm = FORM_LEDGERS.includes(ledgerType);

  function search() {
    const missing: string[] = [];
    if (ledgerType === '') missing.push('장부 종류');
    if (fromDate === '') missing.push('조회 시작일');
    if (toDate === '') missing.push('조회 종료일');
    if (isCash && cashBookScope === '금융기관별' && partnerId === '') missing.push('금융거래처');
    if (isCash && cashBookScope === '프로젝트별' && projectId === '') missing.push('프로젝트');
    if (isCash && cashBookScope === '결의 담당자별' && resolverId === '') missing.push('결의 담당자');
    if (missing.length > 0) {
      setFormError(missing.join(', ') + '을(를) 입력해 주세요.');
      return;
    }
    setFormError('');
    const query: Row = { ledgerType, fromDate, toDate };
    if (isCash) {
      query.cashBookScope = cashBookScope;
      if (cashBookScope === '금융기관별') query.partnerId = partnerId;
      if (cashBookScope === '프로젝트별') query.projectId = projectId;
      if (cashBookScope === '결의 담당자별') query.resolverId = resolverId;
    }
    if (hasForm) query.viewForm = viewForm;
    setPageNo(0);
    setApplied(query);
    notify('예산장부를 조회했습니다.');
  }

  function reset() {
    setLedgerType('');
    setFromDate('');
    setToDate('');
    setCashBookScope('전체');
    setPartnerId('');
    setProjectId('');
    setResolverId('');
    setViewForm('상세');
    setFormError('');
    setApplied(null);
    setPageNo(0);
  }

  const items = data ? data.items : [];
  const totalAmount = items.length > 0 ? items[0].totalAmount : 0;

  return (
    <div className="doc">
      <section className="box">
        <h2>예산장부 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="장부 종류" required>
            <Select value={ledgerType} onChange={setLedgerType} options={LEDGER_TYPES.map((t): [string, string] => [t, t])} placeholder="장부 종류 선택" />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={fromDate} onChange={setFromDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={toDate} onChange={setToDate} />
          </Field>
          {isCash && (
            <Field label="조회 구분">
              <Select value={cashBookScope} onChange={setCashBookScope} options={CASH_SCOPES.map((t): [string, string] => [t, t])} />
            </Field>
          )}
          {isCash && cashBookScope === '금융기관별' && (
            <Field label="금융거래처" required>
              <LookupSelect table="partner" role={role} value={partnerId} onChange={setPartnerId} placeholder="금융거래처 선택" />
            </Field>
          )}
          {isCash && cashBookScope === '프로젝트별' && (
            <Field label="프로젝트" required>
              <LookupSelect table="project" role={role} value={projectId} onChange={setProjectId} placeholder="프로젝트 선택" />
            </Field>
          )}
          {isCash && cashBookScope === '결의 담당자별' && (
            <Field label="결의 담당자" required>
              <LookupSelect table="employee" role={role} value={resolverId} onChange={setResolverId} placeholder="담당자 선택" />
            </Field>
          )}
          {hasForm && (
            <Field label="조회 형태">
              <Select value={viewForm} onChange={setViewForm} options={[['상세', '상세'], ['총괄', '총괄']]} />
            </Field>
          )}
        </Filters>
        {formError !== '' && <ErrorText text={formError} />}
        {error !== '' && <ErrorText text={error} />}
      </section>
      {applied !== null && (
        <section className="box">
          <h2>조회 결과</h2>
          <Tiles items={[['조회 건수', <Num value={data ? data.total : 0} />], ['합계 금액', <Num value={totalAmount} />]]} />
          <Band total={data ? data.total : 0} />
          <DataTable
            columns={[
              { key: 'entryDate', label: '전표 일자', render: (r) => <DateText value={r.entryDate} /> },
              { key: 'summary', label: '적요' },
              { key: 'debitAmount', label: '차변 금액', render: (r) => <Num value={r.debitAmount} /> },
              { key: 'creditAmount', label: '대변 금액', render: (r) => <Num value={r.creditAmount} /> },
              { key: 'resolutionAmount', label: '결의 금액', render: (r) => <Num value={r.resolutionAmount} /> },
            ]}
            rows={items}
            empty={loading ? '불러오는 중입니다.' : '조회 조건에 해당하는 내역이 없습니다. 조건을 바꿔 다시 조회해 주세요.'}
          />
          <Pager page={pageNo} size={SIZE} total={data ? data.total : 0} onPage={setPageNo} />
        </section>
      )}
      {applied === null && <p>장부 종류와 조회 기간을 입력한 뒤 조회해 주세요.</p>}
    </div>
  );
}
